-- S24 Redo the peer test with connected PACs (union and company PACs, whose sponsor pays overhead) taken out, using ORG_TP from the committee dim: cross-section by funding and same-PAC panel, by group
WITH dim AS (SELECT CMTE_ID, MAX(NULLIF(TRIM(ORG_TP),'')) org_tp FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_COMMITTEES_DIM GROUP BY 1),
p AS (SELECT s.CMTE_ID, YEAR(s.COVERAGE_END_DATE) + MOD(YEAR(s.COVERAGE_END_DATE), 2) cyc, s.TOTAL_DISBURSEMENTS disb,
             IFF(s.INDIVIDUAL_CONTRIBUTIONS / NULLIF(s.TOTAL_RECEIPTS,0) >= 0.75, 'indiv75', 'other') funding,
             CASE WHEN s.COMMITTEE_DESIGNATION = 'D' THEN 'leadership'
                  WHEN s.COMMITTEE_DESIGNATION = 'U' AND s.COMMITTEE_TYPE IN ('N','Q') AND dim.org_tp IS NULL THEN 'nonconnected'
                  WHEN s.COMMITTEE_DESIGNATION IN ('U','B') AND s.COMMITTEE_TYPE IN ('N','Q') AND dim.org_tp IS NOT NULL THEN 'connected' END grp,
             (COALESCE(s.CONTRIBUTIONS_TO_OTHER_COMMITTEES,0) + COALESCE(s.INDEPENDENT_EXPENDITURES,0) + COALESCE(s.TRANSFERS_TO_AFFILIATES,0)) / NULLIF(s.TOTAL_DISBURSEMENTS,0) share
      FROM LIBRARY_MARTS.POLITICS.POLITICS__FED_FEC_PAC_SUMMARY s LEFT JOIN dim ON dim.CMTE_ID = s.CMTE_ID
      WHERE s.COVERAGE_END_DATE IS NOT NULL AND s.CMTE_ID NOT IN ('C00828541','C00762591') AND s.TOTAL_DISBURSEMENTS >= 250000),
x AS (SELECT 'cross' kind, grp, cyc::STRING period, funding, COUNT(*) pacs, ROUND(MEDIAN(share),3) med_a, NULL::FLOAT med_b, NULL::FLOAT med_change,
             ROUND(SUM(share*disb)/SUM(disb),3) wshare, NULL::NUMBER fell_25
      FROM p WHERE grp IS NOT NULL GROUP BY 1,2,3,4),
y AS (SELECT 'panel' kind, a.grp, a.cyc || '-' || b.cyc period, 'all' funding, COUNT(*) pacs, ROUND(MEDIAN(a.share),3) med_a, ROUND(MEDIAN(b.share),3) med_b,
             ROUND(MEDIAN(b.share - a.share),3) med_change, ROUND(SUM(b.share*b.disb)/SUM(b.disb) - SUM(a.share*a.disb)/SUM(a.disb),3) wshare, COUNT_IF(b.share < a.share - 0.25) fell_25
      FROM p a JOIN p b ON a.CMTE_ID = b.CMTE_ID AND b.cyc = a.cyc + 2 AND a.grp = b.grp WHERE a.grp IS NOT NULL GROUP BY 1,2,3,4)
SELECT * FROM x UNION ALL SELECT * FROM y ORDER BY 1,2,3,4;

